// Given: V1, energy of a spring under explicit and semi-implicit Euler (pill 1.4).
// Do not edit this file. A static chart with a timestep selector, so it needs
// no animation and suits prefers-reduced-motion.
import { palette } from "../render/colors";
import { springEnergies } from "./algos/eulerSpring";
import { injectStyles } from "./styles";

const SECONDS = 10;
const STEPS = [
  { label: "1/30 s", dt: 1 / 30 },
  { label: "1/60 s", dt: 1 / 60 },
  { label: "1/120 s", dt: 1 / 120 },
];

export function createEulerEnergyVisual(container: HTMLElement): () => void {
  injectStyles();
  const root = document.createElement("div");
  root.className = "pfs-player";
  root.innerHTML = `
    <canvas class="pfs-canvas" style="height:300px" role="img"
      aria-label="Energy over 10 seconds: explicit Euler grows, semi-implicit Euler stays level"></canvas>
    <div class="pfs-controls">
      <label>Timestep <select>${STEPS.map((s, i) => `<option value="${i}"${i === 1 ? " selected" : ""}>${s.label}</option>`).join("")}</select></label>
      <span class="pfs-count"></span>
    </div>
    <dl class="pfs-values"></dl>`;
  container.appendChild(root);
  const canvas = root.querySelector("canvas")!;
  const select = root.querySelector("select")!;
  const values = root.querySelector(".pfs-values")!;
  const ctx = canvas.getContext("2d")!;

  function draw() {
    const pal = palette();
    const { dt } = STEPS[Number(select.value)]!;
    const s = springEnergies(dt, SECONDS);
    const dpr = window.devicePixelRatio || 1;
    const w = canvas.clientWidth;
    const h = canvas.clientHeight;
    canvas.width = Math.round(w * dpr);
    canvas.height = Math.round(h * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.fillStyle = pal.background;
    ctx.fillRect(0, 0, w, h);

    // Log scale on energy relative to the start, so a 10x growth and a 5% wobble both show.
    const pad = { l: 48, r: 12, t: 12, b: 28 };
    const e0 = s.explicit[0]!;
    const ratios = (arr: number[]) => arr.map((e) => e / e0);
    const ex = ratios(s.explicit);
    const si = ratios(s.semiImplicit);
    const maxR = Math.max(2, ...ex);
    const minR = 0.5;
    const X = (t: number) => pad.l + (t / SECONDS) * (w - pad.l - pad.r);
    const Y = (r: number) =>
      pad.t + (1 - Math.log(r / minR) / Math.log(maxR / minR)) * (h - pad.t - pad.b);

    ctx.font = "11px ui-monospace, Menlo, Consolas, monospace";
    ctx.lineWidth = 1;
    for (const r of [0.5, 1, 2, 5, 10, 100, 1000].filter((r) => r <= maxR)) {
      ctx.strokeStyle = r === 1 ? pal.axis : pal.grid;
      ctx.beginPath();
      ctx.moveTo(pad.l, Y(r));
      ctx.lineTo(w - pad.r, Y(r));
      ctx.stroke();
      ctx.fillStyle = pal.muted;
      ctx.fillText(`${r}x`, 6, Y(r) + 4);
    }
    for (let t = 0; t <= SECONDS; t += 2) ctx.fillText(`${t} s`, X(t) - 8, h - 8);

    const line = (arr: number[], color: string) => {
      ctx.strokeStyle = color;
      ctx.lineWidth = 2;
      ctx.beginPath();
      arr.forEach((r, i) =>
        i === 0 ? ctx.moveTo(X(s.t[i]!), Y(r)) : ctx.lineTo(X(s.t[i]!), Y(r)),
      );
      ctx.stroke();
    };
    line(ex, pal.b);
    line(si, pal.a);
    ctx.fillStyle = pal.b;
    ctx.fillText("explicit", w - pad.r - 70, pad.t + 12);
    ctx.fillStyle = pal.a;
    ctx.fillText("semi-implicit", w - pad.r - 98, Y(1) - 8);

    const last = ex.length - 1;
    root.querySelector(".pfs-count")!.textContent = `${last} steps`;
    values.innerHTML = `<dt>explicit after ${SECONDS} s</dt><dd>${ex[last]!.toFixed(1)}x</dd>
      <dt>semi-implicit after ${SECONDS} s</dt><dd>${si[last]!.toFixed(3)}x</dd>`;
  }

  select.addEventListener("change", draw);
  const resize = new ResizeObserver(draw);
  resize.observe(canvas);
  draw();
  return () => {
    resize.disconnect();
    root.remove();
  };
}
